const m = new Map<string, number>();
const k1 = "al" + "pha";
const k2 = ["al", "pha"].join("");
m.set(k1, 1);
console.log(m.get(k2), m.get(k1), m.get("alpha"), m.has("alpha"), m.get("alph"), m.get("alphaa"));
m.delete("alpha");
console.log(m.get(k1), m.get(k2), m.has(k1), m.size);
m.set(k2, 2);
console.log(m.get(k1), m.get(k2), [...m.keys()], m.size);
for (let i = 0; i < 40; i++) m.set("k" + i, i);
for (let i = 0; i < 40; i += 2) m.delete("k" + i);
const probe = "k" + 7;
console.log(m.get(probe), m.get(probe), m.get("k7"));
for (let i = 40; i < 120; i++) m.set("k" + i, i); // growth / compaction
console.log(m.get(probe), m.get("k8"), m.get("k119"), m.size);
m.delete(probe);
console.log(m.get(probe), m.has("k7"));
m.set("k7", 77);
console.log(m.get(probe), [...m.entries()].slice(-2));
m.clear();
console.log(m.get(probe), m.size, m.get(k1));
m.set(probe, 5);
console.log(m.get("k" + 7), m.get(probe));
const s = new Set<string>(["a", "b", "c"]);
const a = "a";
console.log(s.has(a), s.has("a"), s.has("a" + ""), s.delete(a), s.has(a), s.has("a"), [...s]);
s.add("a");
console.log([...s], s.has(a));
const order = new Map<string, number>();
order.set("x", 1); order.set("y", 2); order.set("z", 3);
let seen = "";
order.forEach((v, k) => { seen += k + v; if (k === "x") { order.delete("y"); order.set("w", 9); } });
console.log(seen, order.get("w"), order.get("y"), [...order.keys()]);
const rec: Record<string, number> = {};
const rk = "f" + "oo";
rec[rk] = 1;
rec["bar"] = 2;
console.log(rec["foo"], rec[rk], rec["f" + "oo"], Object.keys(rec), rec["foo"] !== undefined);
delete rec["foo"];
console.log(Object.keys(rec), rec["bar"]);
const keys = ["transform.position", "spin.rate", "controls.player"];
const om = new Map<string, number>();
keys.forEach((k, i) => om.set(k, i));
let tot = 0;
for (let r = 0; r < 1000; r++) for (const k of keys) tot += om.get(k) ?? 100;
console.log(tot, om.get("transform." + "position"));
