// a memoized entry that compaction moved: the old index now holds another
// key (the memo refreshes on its first and every 8th miss — this order
// leaves it naming ek's pre-compaction index)
const mm = new Map<string, number>();
for (let i = 0; i < 16; i++) mm.set("e" + i, i);
const ek = "e" + 10;
for (let i = 0; i < 8; i++) mm.delete("e" + i);
console.log(mm.get(ek), mm.get(ek));
for (let i = 0; i < 10; i++) mm.set("n" + i, 100 + i);
console.log(mm.get(ek), mm.get("e" + 10), [...mm.keys()].indexOf(ek), mm.size);
mm.delete(ek);
console.log(mm.get(ek), mm.has(ek));
